<?php
$payments=json_decode($request['original_data']??'[]',true);$payments=is_array($payments)?$payments:[];$payment=$payments?$payments[0]:[];
$student=!empty($payment['student_id'])?$this->db->where('student_id',$payment['student_id'])->get('student')->row_array():[];
$year=get_settings('running_year');$term=get_settings('running_term');$enroll=!empty($payment['student_id'])?$this->db->where(['student_id'=>$payment['student_id'],'year'=>$year,'term'=>$term])->get('enroll')->row_array():[];
$class=!empty($enroll['class_id'])?$this->db->where('class_id',$enroll['class_id'])->get('class')->row_array():[];$section=!empty($enroll['section_id'])?$this->db->where('section_id',$enroll['section_id'])->get('section')->row_array():[];
$requester=!empty($request['requested_by'])?$this->db->where('admin_id',$request['requested_by'])->get('admin')->row_array():[];
$reviewer_id=(int)($request['approved_by']??0);$reviewer=$reviewer_id?$this->db->where('admin_id',$reviewer_id)->get('admin')->row_array():[];
$new_data=!empty($request['new_data'])?json_decode($request['new_data'],true):[];$new_data=is_array($new_data)?$new_data:[];
$total_amount=array_sum(array_map(function($p){return (float)($p['amount']??0);},$payments));$currency='₵';$status=$request['status']??'pending';
$method_map=['cash'=>'Cash','momo'=>'Mobile Money','cheque'=>'Cheque','bank'=>'Bank'];
?>
