    <div class="evidence-section"><h4>Original Receipt Allocation</h4><div class="evidence-table-shell"><table class="evidence-table"><thead><tr><th>Invoice</th><th>Item</th><th>Amount</th><th>Method</th></tr></thead><tbody><?php if(!$payments): ?><tr><td colspan="4">No original payment snapshot available.</td></tr><?php else: foreach($payments as $p): ?><tr><td>#<?php echo html_escape((string)($p['invoice_code']??'')); ?></td><td><?php echo html_escape($p['title']??''); ?></td><td><?php echo $currency.' '.number_format((float)($p['amount']??0),2); ?></td><td><?php $pm=$p['payment_method']??'';echo html_escape($method_map[$pm]??ucfirst((string)$pm)); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
